123	void TcpStatsdSink::flush(Stats::MetricSnapshot& snapshot) {
124	  TlsSink& tls_sink = tls_->getTyped<TlsSink>();
125	  tls_sink.beginFlush(true);
126	  for (const auto& counter : snapshot.counters()) {
127	    if (counter.counter_.get().used()) {
128	      tls_sink.flushCounter(counter.counter_.get().name(), counter.delta_);
129	    }
130	  }
131	
132	  for (const auto& gauge : snapshot.gauges()) {
133	    if (gauge.get().used()) {
134	      tls_sink.flushGauge(gauge.get().name(), gauge.get().value());
135	    }
136	  }
137	  tls_sink.endFlush(true);
138	}
