121	// There is no portable way to initialize sockaddr_in6 with a static initializer, do it with a
122	// helper function instead.
123	sockaddr_in6 sockaddrIn6Any() {
124	  sockaddr_in6 v6any = {};
125	  v6any.sin6_family = AF_INET6;
126	  v6any.sin6_addr = in6addr_any;
127	
128	  return v6any;
129	}
