21	
22	  const auto& statsd_sink =
23	      MessageUtil::downcastAndValidate<const envoy::config::metrics::v3::StatsdSink&>(
24	          config, server.messageValidationContext().staticValidationVisitor());
25	  switch (statsd_sink.statsd_specifier_case()) {
26	  case envoy::config::metrics::v3::StatsdSink::StatsdSpecifierCase::kAddress: {
27	    Network::Address::InstanceConstSharedPtr address =
28	        Network::Address::resolveProtoAddress(statsd_sink.address());
29	    ENVOY_LOG(debug, "statsd UDP ip address: {}", address->asString());
30	    return std::make_unique<Common::Statsd::UdpStatsdSink>(server.threadLocal(), std::move(address),
31	                                                           false, statsd_sink.prefix());
32	  }
33	  case envoy::config::metrics::v3::StatsdSink::StatsdSpecifierCase::kTcpClusterName:
34	    ENVOY_LOG(debug, "statsd TCP cluster: {}", statsd_sink.tcp_cluster_name());
35	    return std::make_unique<Common::Statsd::TcpStatsdSink>(
36	        server.localInfo(), statsd_sink.tcp_cluster_name(), server.threadLocal(),
37	        server.clusterManager(), server.stats(), statsd_sink.prefix());
38	  default:
39	    // Verified by schema.
40	    NOT_REACHED_GCOVR_EXCL_LINE;
41	  }
